package gnochat

import (
	"chain"
	"strings"
	"time"
	"unicode/utf8"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
)

var (
	channelSequence seqid.ID
	channels        = avl.NewTree() // seqid string -> *Channel
)

// CreateChannel creates a public channel and makes the caller its owner.
func CreateChannel(cur realm, name, description string) string {
	name = strings.TrimSpace(name)
	description = strings.TrimSpace(description)
	assertValidChannelName(name)
	assertValidChannelDescription(description)

	owner := cur.Previous().Address()
	id := channelSequence.Next()
	channel := &Channel{
		id:          id,
		name:        name,
		description: description,
		owner:       owner,
		createdAt:   time.Now(),
		members:     avl.NewTree(),
		messages:    avl.NewTree(),
	}
	channel.members.Set(owner.String(), &Member{
		addr:     owner,
		role:     RoleOwner,
		joinedAt: time.Now(),
	})
	channels.Set(id.String(), channel)

	chain.Emit(
		"ChannelCreated",
		"channelID", id.String(),
		"owner", owner.String(),
		"name", name,
	)
	return id.String()
}

// JoinChannel adds the caller to a public channel as a member.
func JoinChannel(cur realm, channelID string) {
	channel := mustGetChannel(channelID)
	caller := cur.Previous().Address()
	if channel.members.Has(caller.String()) {
		panic("already a channel member")
	}

	channel.members.Set(caller.String(), &Member{
		addr:     caller,
		role:     RoleMember,
		joinedAt: time.Now(),
	})
	chain.Emit(
		"ChannelJoined",
		"channelID", channel.id.String(),
		"member", caller.String(),
	)
}

// SetMemberRole promotes or demotes a member. Only the channel owner may do so.
func SetMemberRole(cur realm, channelID string, member address, role string) {
	channel := mustGetChannel(channelID)
	caller := cur.Previous().Address()
	assertOwner(channel, caller)
	assertValidManagedRole(role)
	if member == channel.owner {
		panic("the owner role cannot be changed")
	}

	target := mustGetMember(channel, member)
	target.role = role
	chain.Emit(
		"MemberRoleChanged",
		"channelID", channel.id.String(),
		"member", member.String(),
		"role", role,
		"caller", caller.String(),
	)
}

// MuteMember changes whether a member may post. Owners and admins may mute
// regular members; only the owner may mute an admin.
func MuteMember(cur realm, channelID string, member address, muted bool) {
	channel := mustGetChannel(channelID)
	caller := cur.Previous().Address()
	actor := mustGetMember(channel, caller)
	if actor.role != RoleOwner && actor.role != RoleAdmin {
		panic("only owners and admins can mute members")
	}
	if member == channel.owner {
		panic("the channel owner cannot be muted")
	}
	if member == caller {
		panic("members cannot mute themselves")
	}

	target := mustGetMember(channel, member)
	if target.role == RoleAdmin && actor.role != RoleOwner {
		panic("only the owner can mute an admin")
	}
	target.muted = muted

	chain.Emit(
		"MemberMuteChanged",
		"channelID", channel.id.String(),
		"member", member.String(),
		"muted", boolString(muted),
		"caller", caller.String(),
	)
}

func ChannelCount() int {
	return channels.Size()
}

func GetChannel(channelID string) (ChannelView, bool) {
	channel, found := getChannel(channelID)
	if !found {
		return ChannelView{}, false
	}
	return channel.view(), true
}

// ChannelAt returns browser-friendly scalar fields for the channel at index.
// Keeping this query separate from GetChannel avoids making clients decode Gno
// structs such as address and time.Time over JSON-RPC.
func ChannelAt(index int) (
	id, name, description, owner string,
	createdAt int64,
	memberCount, messageCount int,
	found bool,
) {
	if index < 0 || index >= channels.Size() {
		return "", "", "", "", 0, 0, 0, false
	}

	_, raw := channels.GetByIndex(index)
	channel := raw.(*Channel)
	return channel.id.String(), channel.name, channel.description,
		channel.owner.String(), channel.createdAt.Unix(),
		channel.members.Size(), channel.messages.Size(), true
}

func IsMember(channelID string, member address) bool {
	channel := mustGetChannel(channelID)
	return channel.members.Has(member.String())
}

func GetMemberRole(channelID string, member address) (string, bool) {
	channel := mustGetChannel(channelID)
	raw := channel.members.Get(member.String())
	if raw == nil {
		return "", false
	}
	return raw.(*Member).role, true
}

func IsMuted(channelID string, member address) bool {
	channel := mustGetChannel(channelID)
	return mustGetMember(channel, member).muted
}

func getChannel(channelID string) (*Channel, bool) {
	id, err := seqid.FromString(channelID)
	if err != nil || id == 0 {
		return nil, false
	}
	raw := channels.Get(id.String())
	if raw == nil {
		return nil, false
	}
	return raw.(*Channel), true
}

func mustGetChannel(channelID string) *Channel {
	channel, found := getChannel(channelID)
	if !found {
		panic("channel not found")
	}
	return channel
}

func mustGetMember(channel *Channel, member address) *Member {
	raw := channel.members.Get(member.String())
	if raw == nil {
		panic("channel member not found")
	}
	return raw.(*Member)
}

func assertOwner(channel *Channel, caller address) {
	if caller != channel.owner {
		panic("only the channel owner may perform this action")
	}
}

func assertValidManagedRole(role string) {
	if role != RoleAdmin && role != RoleMember {
		panic("role must be admin or member")
	}
}

func assertValidChannelName(name string) {
	length := utf8.RuneCountInString(name)
	if length < 3 {
		panic("channel name must contain at least 3 characters")
	}
	if length > MaxChannelNameLength {
		panic("channel name is too long")
	}
}

func assertValidChannelDescription(description string) {
	if utf8.RuneCountInString(description) > MaxChannelDescriptionLength {
		panic("channel description is too long")
	}
}

func boolString(value bool) string {
	if value {
		return "true"
	}
	return "false"
}

package gnochat

import (
	"chain"
	"strings"
	"time"
	"unicode/utf8"

	"gno.land/p/nt/seqid/v0"
)

// PostMessage stores one short public message on-chain.
func PostMessage(cur realm, channelID, content string) string {
	channel := mustGetChannel(channelID)
	caller := cur.Previous().Address()
	rawMember := channel.members.Get(caller.String())
	if rawMember == nil {
		panic("only channel members can post")
	}
	member := rawMember.(*Member)
	if member.muted {
		panic("member is muted")
	}

	content = strings.TrimSpace(content)
	assertValidMessage(content)
	id := channel.messageSequence.Next()
	message := &Message{
		id:        id,
		author:    caller,
		content:   content,
		createdAt: time.Now(),
	}
	channel.messages.Set(id.String(), message)

	chain.Emit(
		"MessagePosted",
		"channelID", channel.id.String(),
		"messageID", id.String(),
		"author", caller.String(),
	)
	return id.String()
}

func MessageCount(channelID string) int {
	return mustGetChannel(channelID).messages.Size()
}

func GetMessage(channelID, messageID string) (MessageView, bool) {
	channel := mustGetChannel(channelID)
	id, err := seqid.FromString(messageID)
	if err != nil || id == 0 {
		return MessageView{}, false
	}
	raw := channel.messages.Get(id.String())
	if raw == nil {
		return MessageView{}, false
	}
	return raw.(*Message).view(), true
}

// MessageAt returns browser-friendly scalar fields for one message at index.
func MessageAt(channelID string, index int) (
	id, author, content string,
	createdAt int64,
	found bool,
) {
	channel, channelFound := getChannel(channelID)
	if !channelFound || index < 0 || index >= channel.messages.Size() {
		return "", "", "", 0, false
	}

	_, raw := channel.messages.GetByIndex(index)
	message := raw.(*Message)
	return message.id.String(), message.author.String(), message.content,
		message.createdAt.Unix(), true
}

func assertValidMessage(content string) {
	if content == "" {
		panic("message cannot be empty")
	}
	if utf8.RuneCountInString(content) > MaxMessageLength {
		panic("message is too long")
	}
}

package gnochat

import (
	"strconv"
	"strings"

	"gno.land/p/moul/md"
	"gno.land/p/nt/markdown/sanitize/v0"
)

// Render exposes a simple read-only UI through gnoweb.
// All persisted user input is sanitized before being returned as Markdown.
func Render(path string) string {
	path = strings.Trim(path, "/")
	if path == "" {
		return renderChannelList()
	}
	if strings.HasPrefix(path, "c/") {
		return renderChannel(strings.TrimPrefix(path, "c/"))
	}
	return md.H1("GnoChat") + "Page not found.\n"
}

func renderChannelList() string {
	out := md.H1("GnoChat")
	out += "Public, wallet-owned channels on Gno.land.\n\n"
	if channels.Size() == 0 {
		return out + "No channels yet. Call `CreateChannel` to create one.\n"
	}

	channels.Iterate("", "", func(_ string, raw any) bool {
		channel := raw.(*Channel)
		out += md.H3(md.Link(channel.name, "c/"+channel.id.String()))
		if channel.description != "" {
			out += sanitize.Block(channel.description) + "\n\n"
		}
		out += strconv.Itoa(channel.members.Size()) + " members · "
		out += strconv.Itoa(channel.messages.Size()) + " messages\n\n"
		return false
	})
	return out
}

func renderChannel(channelID string) string {
	channel, found := getChannel(channelID)
	if !found {
		return md.H1("GnoChat") + "Channel not found.\n"
	}

	out := md.H1(sanitize.InlineText(channel.name))
	if channel.description != "" {
		out += sanitize.Block(channel.description) + "\n\n"
	}
	out += "Owner: " + md.InlineCode(channel.owner.String()) + "\n\n"
	out += strconv.Itoa(channel.members.Size()) + " members · "
	out += strconv.Itoa(channel.messages.Size()) + " messages\n\n"
	out += md.HorizontalRule()

	if channel.messages.Size() == 0 {
		return out + "No messages yet.\n"
	}

	channel.messages.Iterate("", "", func(_ string, raw any) bool {
		message := raw.(*Message)
		out += md.H4("Message " + sanitize.InlineText(message.id.String()))
		out += sanitize.Block(message.content) + "\n\n"
		out += "— " + md.InlineCode(message.author.String()) + ", "
		out += sanitize.InlineText(message.createdAt.Format("02 Jan 2006, 15:04")) + "\n\n"
		return false
	})
	return out
}

package gnochat

import (
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
)

const (
	RoleOwner  = "owner"
	RoleAdmin  = "admin"
	RoleMember = "member"
)

const (
	MaxChannelNameLength        = 50
	MaxChannelDescriptionLength = 280
	MaxMessageLength            = 500
)

// Channel is the persisted state for one public chat channel.
// Members and messages use AVL trees so lookups stay efficient as they grow.
type Channel struct {
	id              seqid.ID
	name            string
	description     string
	owner           address
	createdAt       time.Time
	members         *avl.Tree // address string -> *Member
	messages        *avl.Tree // seqid string -> *Message
	messageSequence seqid.ID
}

type Member struct {
	addr     address
	role     string
	muted    bool
	joinedAt time.Time
}

type Message struct {
	id        seqid.ID
	author    address
	content   string
	createdAt time.Time
}

// ChannelView is a read-only copy returned to clients.
type ChannelView struct {
	ID           string
	Name         string
	Description  string
	Owner        address
	CreatedAt    time.Time
	MemberCount  int
	MessageCount int
}

// MessageView is a read-only copy returned to clients.
type MessageView struct {
	ID        string
	Author    address
	Content   string
	CreatedAt time.Time
}

func (c *Channel) view() ChannelView {
	return ChannelView{
		ID:           c.id.String(),
		Name:         c.name,
		Description:  c.description,
		Owner:        c.owner,
		CreatedAt:    c.createdAt,
		MemberCount:  c.members.Size(),
		MessageCount: c.messages.Size(),
	}
}

func (m *Message) view() MessageView {
	return MessageView{
		ID:        m.id.String(),
		Author:    m.author,
		Content:   m.content,
		CreatedAt: m.createdAt,
	}
}
